{"rules": [
  {
    "category": "rent_increase_limit",
    "title": "Rent Board Housing Inventory Reporting License Requirement",
    "requirement": "Landlords must comply with annual Rent Board inventory reporting requirements to maintain a license to impose annual or banked rent increases; rent increases are prohibited during any period of noncompliance.",
    "requirement_es": "Los propietarios deben cumplir con los requisitos anuales de información del inventario del Rent Board para conservar la licencia para imponer aumentos de renta anuales o acumulados; los aumentos están prohibidos durante cualquier período de incumplimiento.",
    "key_value": null,
    "coverage_conditions": {
      "type": "ALWAYS",
      "clauses": []
    },
    "exemptions": [
      {
        "description": "Owner-occupied units that are not rented at any time are not required to report additional rental information.",
        "conditions": {
          "type": "AND",
          "clauses": [
            {
              "field": "owner_occupied",
              "operator": "==",
              "value": true,
              "note": "occupied by an owner of record on either a full-time or part-time basis and is not rented at any time"
            }
          ]
        }
      }
    ],
    "effective_date": "2021-01-18",
    "superseded_date": null,
    "status": "enacted",
    "precedence": {
      "relationship": "stacks_with",
      "target_scope": "none",
      "source_language": null
    },
    "penalty": "License to impose rent increases is suspended during noncompliance; tenant is not obligated to pay increased rent for months during suspension.",
    "source_citation": "S.F. Admin. Code § 37.15(e)",
    "quote": {
      "chunk": "c2962",
      "start_words": "If a landlord has substantially complied with",
      "end_words": "during the period of suspension."
    },
    "confidence": 0.95
  }
]}
